package com.bank.sparkarch.task;

import com.bank.sparkarch.model.Txn;
import java.math.BigDecimal;
import java.util.List;

// The smallest unit of work: one Task processes exactly ONE partition.
public class Task {
    private final int partitionId;
    private final List<Txn> partition; // the single partition this task owns

    public Task(int partitionId, List<Txn> partition) {
        this.partitionId = partitionId;
        this.partition = partition;
    }

    public int getPartitionId() { return partitionId; }

    // The "computation function per partition" — here, sum the amounts.
    public BigDecimal compute() {
        BigDecimal sum = BigDecimal.ZERO;
        for (Txn t : partition) {
            sum = sum.add(t.getAmount());
        }
        return sum;
    }
}
