package com.bank.sparkarch.executor;

import com.bank.sparkarch.task.Task;
import java.math.BigDecimal;
import java.util.concurrent.Callable;
import java.util.logging.Logger;

// An Executor is a long-lived JVM worker. Here one Executor runs one Task.
// In real Spark an Executor runs many Tasks concurrently (one per core).
public class Executor implements Callable<BigDecimal> {
    private static final Logger log = Logger.getLogger(Executor.class.getName());
    private final String executorId;
    private final Task task;

    public Executor(String executorId, Task task) {
        this.executorId = executorId;
        this.task = task;
    }

    @Override
    public BigDecimal call() {
        log.info(() -> executorId + " running Task for partition " + task.getPartitionId());
        BigDecimal partial = task.compute();
        log.fine(() -> executorId + " partition " + task.getPartitionId() + " partial=" + partial);
        return partial;
    }
}
