package com.bank.sparkarch.cluster;

import com.bank.sparkarch.executor.Executor;
import com.bank.sparkarch.task.Task;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;
import java.util.logging.Logger;

// The Cluster Manager allocates compute (a thread pool here) and launches Executors.
public class ClusterManager {
    private static final Logger log = Logger.getLogger(ClusterManager.class.getName());
    private final int executorCores;

    public ClusterManager(int executorCores) {
        this.executorCores = executorCores; // total parallelism we can grant
    }

    // Launch one Executor per Task, bounded by available cores, and collect results.
    public List<BigDecimal> runTasks(List<Task> tasks) {
        log.info(() -> "ClusterManager allocating " + executorCores
                + " cores for " + tasks.size() + " tasks");
        ExecutorService pool = Executors.newFixedThreadPool(executorCores);
        List<Future<BigDecimal>> futures = new ArrayList<>();
        try {
            int i = 0;
            for (Task t : tasks) {
                Executor exec = new Executor("Executor-" + (i++ % executorCores), t);
                futures.add(pool.submit(exec));
            }
            List<BigDecimal> partials = new ArrayList<>();
            for (Future<BigDecimal> f : futures) {
                partials.add(f.get()); // wait for each task's partial result
            }
            return partials;
        } catch (InterruptedException | ExecutionException e) {
            Thread.currentThread().interrupt();
            throw new IllegalStateException("Task execution failed", e);
        } finally {
            pool.shutdown();
        }
    }
}
