package com.bank.sparkarch.driver;

import com.bank.sparkarch.cluster.ClusterManager;
import com.bank.sparkarch.model.Txn;
import com.bank.sparkarch.task.Task;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// The Driver is the master: it builds the plan, partitions the data,
// creates one Task per partition, submits to the Cluster Manager, and
// aggregates the final result (like an action such as reduce/collect).
public class Driver {
    private static final Logger log = Logger.getLogger(Driver.class.getName());
    private final ClusterManager clusterManager;

    public Driver(ClusterManager clusterManager) {
        this.clusterManager = clusterManager;
    }

    // Split data into N partitions — this decides how many Tasks are created.
    private List<List<Txn>> partition(List<Txn> data, int numPartitions) {
        List<List<Txn>> parts = new ArrayList<>();
        for (int i = 0; i < numPartitions; i++) parts.add(new ArrayList<>());
        for (int i = 0; i < data.size(); i++) {
            parts.get(i % numPartitions).add(data.get(i)); // round-robin
        }
        return parts;
    }

    public BigDecimal totalAmount(List<Txn> data, int numPartitions) {
        log.info(() -> "Driver planning job: " + numPartitions
                + " partitions => " + numPartitions + " tasks");
        List<List<Txn>> parts = partition(data, numPartitions);

        // One Task per partition — the core Spark rule.
        List<Task> tasks = new ArrayList<>();
        for (int p = 0; p < parts.size(); p++) {
            tasks.add(new Task(p, parts.get(p)));
        }

        // Submit to the Cluster Manager, which runs them on Executors.
        List<BigDecimal> partials = clusterManager.runTasks(tasks);

        // The Driver aggregates partial results into the final answer.
        BigDecimal total = BigDecimal.ZERO;
        for (BigDecimal p : partials) total = total.add(p);
        log.info(() -> "Driver collected final total = " + total);
        return total;
    }
}
