package com.bank.sparkarch;

import com.bank.sparkarch.cluster.ClusterManager;
import com.bank.sparkarch.driver.Driver;
import com.bank.sparkarch.model.Txn;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.*;

public class SparkArchDemo {
    private static final Logger log = Logger.getLogger(SparkArchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        // Build a dataset of transactions for Rajesh (SAV2001) and Priya (CUR3001).
        List<Txn> data = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            data.add(new Txn("SAV2001", new BigDecimal("1000")));
            data.add(new Txn("CUR3001", new BigDecimal("500")));
        }

        // Cluster Manager grants 4 cores; Driver splits into 8 partitions (8 tasks).
        ClusterManager cm = new ClusterManager(4);
        Driver driver = new Driver(cm);
        BigDecimal total = driver.totalAmount(data, 8);

        log.info(() -> "Nightly report total transaction amount = Rs." + total);
    }
}

